[CmdletBinding()]
param([Parameter(Mandatory)][string]$ExecutablePath,[Parameter(Mandatory)][string]$OutputDirectory,[Parameter(Mandatory)][string]$ReportPath,[ValidateNotNullOrEmpty()][string[]]$CaseFilter=@('*'),[switch]$Large,[ValidateRange(32769,65535)][int]$LargeFileCount=32769)
$ErrorActionPreference='Stop'
# 想定する失敗: private file journal/PIDL/stage生成、dry-runの変更、Shell以外のfallback、
# nativeID/ACL/全stream/link関係の欠落、衝突上書き、preflight一部削除、並列入力順の破損、
# 予算によるBin消費、古いfile restore入口/MCPtool残存、曖昧結果の自動再送。
$repo=[IO.Path]::GetFullPath((Split-Path $PSScriptRoot -Parent))
. (Join-Path $PSScriptRoot 'Verification-Common.ps1')
foreach($path in @($ExecutablePath,$OutputDirectory,$ReportPath)){if(![IO.Path]::IsPathFullyQualified($path)){throw 'Absolute paths required'}}
foreach($path in @($OutputDirectory,$ReportPath)){Assert-VerificationDestination $path @($repo,(Join-Path $env:USERPROFILE '.codex'));if(![IO.Path]::GetPathRoot($path).Equals('D:\',[StringComparison]::OrdinalIgnoreCase)){throw 'External D output required'};if(Test-Path -LiteralPath $path){throw 'Unused output/report required'};if(![IO.Directory]::Exists([IO.Path]::GetDirectoryName($path))){throw 'Output parent must exist'}}
if(![IO.File]::Exists($ExecutablePath)){throw 'Executable missing'}
$null=[IO.Directory]::CreateDirectory($OutputDirectory);$script:temp=Join-Path $OutputDirectory 'temp';$null=[IO.Directory]::CreateDirectory($script:temp)
$oldTemp=$env:TEMP;$oldTmp=$env:TMP;$env:TEMP=$script:temp;$env:TMP=$script:temp
$helperFiles=@('NativeShellFixture.cs','FixtureNative.cs','OwnedBinLocator.cs')|ForEach-Object {Join-Path (Join-Path $PSScriptRoot 'recordless-e2e') $_}
$common=Join-Path $PSScriptRoot 'recordless-e2e/Common.ps1';. $common
$initialSourceHash=(Get-FileHash $PSCommandPath).Hash;$initialSources=@(@($PSCommandPath,$common,(Join-Path $PSScriptRoot 'Verify-RecycleBin.ps1'))+$helperFiles|ForEach-Object {@{path=$_;sha256=(Get-FileHash $_).Hash}});$results=[Collections.Generic.List[object]]::new();$script:commands=[Collections.Generic.List[object]]::new();$catalog=[Collections.Generic.List[string]]::new();$excluded=[Collections.Generic.List[string]]::new()
function Case-R([string]$Name,[scriptblock]$Body,[switch]$RequiresLarge){$catalog.Add($Name);if(($RequiresLarge-and!$Large)-or!@($CaseFilter|Where-Object {$Name-like$_}).Count){$excluded.Add($Name);return};$script:observed=@{};$script:skipReason=$null;$clock=[Diagnostics.Stopwatch]::StartNew();try{& $Body;$results.Add(@{name=$Name;passed=$(if($script:skipReason){$null}else{$true});skipped=[bool]$script:skipReason;note=$script:skipReason;observed=$script:observed;elapsedMs=$clock.ElapsedMilliseconds})}catch{$results.Add(@{name=$Name;passed=$false;error=$_.Exception.Message;stack=$_.ScriptStackTrace;observed=$script:observed;elapsedMs=$clock.ElapsedMilliseconds})}}
try{
