 Case-R 'cli-file-ads-native-windows-roundtrip' {$s=New-ScopeR 'file';$p=File-R $s '空白 & 日本語.txt';[IO.File]::WriteAllText($p+':proof','ADS proof',$utf8);$before=Snapshot-R $p;$prior=Before-BinR $before;$r=Delete-R $s @($p);Assert-WireR $r @($p) @('recycled');Assert-R ($r.exitCode-eq0-and![IO.File]::Exists($p)) 'CLI recycling failed';No-FileRecordsR $s;$null=Restore-BinR $s $p $before $prior}
