 Case-R 'cli-nonrecursive-nonempty-preserved' {$s=New-ScopeR 'nonrecursive';$null=File-R $s 'tree/file';$p=Join-Path $s.files 'tree';$before=Snapshot-R $p;$r=Delete-R $s @($p);Assert-R ($r.exitCode-ne0) 'Nonrecursive nonempty directory accepted';$null=Assert-SnapshotR $p $before;No-FileRecordsR $s}
