 Case-R 'cli-one-invalid-target-preserves-whole-batch' {$s=New-ScopeR 'preflight';$good=File-R $s 'good';$bad=File-R $s 'tree/child';$bad=Split-Path $bad;$before=Snapshot-R $s.files;$r=Delete-R $s @($good,$bad);Assert-R ($r.exitCode-ne0) 'Invalid nonrecursive target accepted';$null=Assert-SnapshotR $s.files $before;No-FileRecordsR $s}
