 Case-R 'cli-hardlink-surviving-alias-preserved' {$s=New-ScopeR 'hardlink';$p=File-R $s 'first';$alias=Join-Path $s.files 'survivor';[Prunlet.RecordlessE2E.FixtureNative]::CreateHardlink($alias,$p);$before=Snapshot-R $p;$aliasBefore=Snapshot-R $alias;$prior=Before-BinR $before;$r=Delete-R $s @($p);Assert-WireR $r @($p) @('recycled');Assert-R ($r.exitCode-eq0) 'Hardlink recycle failed';$script:observed.survivingAliasInBin=Assert-SnapshotR $alias $aliasBefore -WindowsManagedBin;$null=Restore-BinR $s $p $before $prior;$null=Assert-SnapshotR $alias $aliasBefore -WindowsInheritance}
