 Case-R 'cli-budget-and-purge-cannot-consume-bin' {$s=New-ScopeR 'budget';$prepared=Invoke-R $s @('migrate','--apply');Assert-R ($prepared.exitCode-eq0-and$prepared.json.registryReady-and$prepared.json.complete) 'Empty registry namespace preparation failed';$s.expectedMetadataMembers=@(Get-ChildItem -LiteralPath $s.metadata -Force -Recurse|ForEach-Object {$_.FullName.Substring($s.metadata.Length+1)});$p=File-R $s 'budget' 4096;$before=Snapshot-R $p;$prior=Before-BinR $before;$config=Get-Content $s.config -Raw|ConvertFrom-Json -AsHashtable;$config.maxRecoveryBytes=1;$config.retentionDays=1;Save-R $s.config $config;$r=Delete-R $s @($p);Assert-WireR $r @($p) @('recycled');$item=[Prunlet.RecordlessE2E.OwnedBinLocator]::FindNew($before[0].Id,$prior);$bin=Snapshot-R $item.PhysicalPath;foreach($args in @(@('maintain','--dry-run'),@('maintain','--apply'))){$r=Invoke-R $s $args;Assert-R ($r.exitCode-eq0) 'Registry-only maintenance failed';$null=Assert-SnapshotR $item.PhysicalPath $bin};$r=Invoke-R $s @('purge',[guid]::NewGuid().ToString('N'),'--apply');$null=Assert-SnapshotR $item.PhysicalPath $bin;$null=Restore-BinR $s $p $before $prior}
 Case-R 'cli-locked-preflight-retains-all-originals' {$s=New-ScopeR 'locked';$p=File-R $s 'locked';$other=File-R $s 'other';$before=Snapshot-R $s.files;$hold=[Prunlet.RecordlessE2E.FixtureNative]::HoldNoDelete($p);try{$r=Delete-R $s @($other,$p);Assert-R ($r.exitCode-ne0) 'Sharing violation did not fail whole preflight'}finally{$hold.Dispose()};$null=Assert-SnapshotR $s.files $before;No-FileRecordsR $s}
 Case-R 'cli-metadata-target-protection-preserves-originals' {$s=New-ScopeR 'protected';$p=File-R $s 'source';$before=Snapshot-R $p;$metadata=Metadata-R $s.metadata;$r=Delete-R $s @($p,$s.metadata) -Recursive;Assert-R ($r.exitCode-ne0-and(Metadata-R $s.metadata)-ceq$metadata) 'Protected metadata target accepted/modified';$null=Assert-SnapshotR $p $before}
 Case-R 'hook-refuses-raw-delete-without-input-rewrite' {$s=New-ScopeR 'hook';$p=File-R $s 'source';$before=Snapshot-R $p;$input=@{hook_event_name='PreToolUse';tool_name='Bash';tool_input=@{command="Remove-Item -LiteralPath '$p'";cwd=$s.files}}|ConvertTo-Json -Depth 10 -Compress;$r=Invoke-R $s @('hook') $input;Assert-R ($r.exitCode-eq0-and$r.json.hookSpecificOutput.permissionDecision-ceq'deny'-and!$r.json.hookSpecificOutput.updatedInput-and$r.stdout-match'(?i)prunlet') 'Hook did not refuse with guidance';$null=Assert-SnapshotR $p $before;No-FileRecordsR $s}
 Case-R 'mcp-exact-five-tools-and-no-file-restore' {$s=New-ScopeR 'mcp-tools';$session=Open-McpR $s;try{Init-McpR $session;$r=Rpc-R $session @{jsonrpc='2.0';id=2;method='tools/list'};$names=@($r.result.tools.name|Sort-Object);$script:observed.tools=$names;Assert-R (($names-join',')-ceq'delete_files,delete_registry,list_operations,reconcile_registry,restore_registry') 'MCP must expose exactly the five current tools';$r=Call-McpR $session 3 'restore_files' @{operationId=[guid]::NewGuid().ToString('N')};Assert-R $r.failed 'Removed file restore tool is still callable'}finally{Close-McpR $session};No-FileRecordsR $s}
 Case-R 'mcp-file-dry-run-and-native-windows-roundtrip' {$s=New-ScopeR 'mcp-file';$p=File-R $s 'MCP 空白 & source';[IO.File]::WriteAllText($p+':ads','MCP ADS',$utf8);$before=Snapshot-R $p;$prior=Before-BinR $before;$metadata=Metadata-R $s.metadata;$session=Open-McpR $s;try{Init-McpR $session;$r=Call-McpR $session 2 'delete_files' @{paths=@($p);dryRun=$true};Assert-R (!$r.failed) 'MCP dry-run failed';Assert-WireR $r @($p) @('would_recycle') $true;Assert-R ((Metadata-R $s.metadata)-ceq$metadata) 'MCP dry-run wrote metadata';$null=Assert-SnapshotR $p $before;$r=Call-McpR $session 3 'delete_files' @{paths=@($p)};Assert-R (!$r.failed) 'MCP recycle failed';Assert-WireR $r @($p) @('recycled')}finally{Close-McpR $session};No-FileRecordsR $s;$null=Restore-BinR $s $p $before $prior}
