 Case-R 'cli-partial-ambiguous-oversized-sparse-is-not-retried' {
  $s=New-ScopeR 'partial-ambiguous';$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile((Join-Path $PSScriptRoot 'Verify-RecycleBin.ps1'),[ref]$tokens,[ref]$errors);$definitions=@($ast.FindAll({param($n)$n-is[Management.Automation.Language.StringConstantExpressionAst]-and$n.Value.Contains('public static class PrunletSparseE2E {')},$true));Assert-R ($definitions.Count-eq1-and$errors.Count-eq0) 'Sparse finalizer source ambiguous';if(!('PrunletSparseE2E'-as[type])){Add-Type -TypeDefinition $definitions[0].Value}
  $p=Join-Path $s.files 'huge-sparse';$prefix=$utf8.GetBytes('owned sparse prefix; allocated tails must stay zero');$logical=[long]1099511627776;$stream=[IO.FileStream]::new($p,[IO.FileMode]::CreateNew,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);try{[PrunletSparseE2E]::MakeSparse($stream.SafeFileHandle);$stream.Write($prefix,0,$prefix.Length);$stream.SetLength($logical);$stream.Flush($true)}finally{$stream.Dispose()};$proof=[PrunletSparseE2E]::CaptureProof($p);$priorSparse=[string[]]@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($proof.Id)|ForEach-Object Pidl);$good=File-R $s 'ordinary';$goodBefore=Snapshot-R $good;$priorGood=Before-BinR $goodBefore;$bodyError=$null
  try{
   $r=Delete-R $s @($good,$p);$script:observed.partial=$r;Assert-WireR $r @($good,$p) @('recycled','ambiguous');Assert-R ($r.exitCode-ne0-and$r.json.items[1].error.Contains('Inspect the Windows Recycle Bin')) 'Ambiguous failure lacked inspection guidance';Assert-R ([IO.File]::Exists($p)) 'Oversized source not retained';$after=[PrunletSparseE2E]::CaptureProof($p);$script:observed.sparse=@{before=$proof;after=$after};foreach($field in @('Id','SecurityBase64','Attributes','Length','NumberOfLinks')){Assert-R ($proof.$field-ceq$after.$field) ('Sparse source '+$field+' changed')};$null=Restore-BinR $s $good $goodBefore $priorGood;No-FileRecordsR $s
  }catch{$bodyError=$_.Exception.ToString();throw}
  finally{
   $script:observed.bodyError=$bodyError
   if(![IO.File]::Exists($p)){$owned=[Prunlet.RecordlessE2E.OwnedBinLocator]::FindNew($proof.Id,$priorSparse);$null=[Prunlet.RecordlessE2E.FixtureNative]::RestoreOwned($owned.Pidl,$owned.PhysicalPath,$proof.Id,$p,$s.files)}
   $finalizer=[PrunletSparseE2E]::RestoreTiny($p,$proof.Id,$proof.SecurityBase64,[int]$proof.Attributes,$logical,$prefix,[ulong]1048576);$script:observed.sparseFinalizer=$finalizer;Assert-R $finalizer.Success ('Owned sparse tiny finalization failed: '+$finalizer.Error)
  }
 }
 Case-R 'cli-case-sensitive-directory-preserves-both-names' {
  $s=New-ScopeR 'case-sensitive';$p=Join-Path $s.files 'case-sensitive';$null=[IO.Directory]::CreateDirectory($p);$beforeRoot=Snapshot-R $p
  $fsutil=Join-Path $env:SystemRoot 'System32/fsutil.exe';$output=@(& $fsutil file SetCaseSensitiveInfo $p enable 2>&1);$code=$LASTEXITCODE;$script:observed.enable=@{exitCode=$code;output=$output}
  $nativeCaseSensitive=[Prunlet.RecordlessE2E.FixtureNative]::IsCaseSensitive($p);$script:observed.enable.nativeFlag=$nativeCaseSensitive;if($code-ne0-or!$nativeCaseSensitive){Assert-R (($output-join' ')-match'(?i)access|denied|support|privilege|拒否|サポート|権限') 'Unknown case-sensitive setup failure';$null=Assert-SnapshotR $p $beforeRoot;$script:skipReason='Case-sensitive boundary unverified: native fsutil refused this token/filesystem.';return}
  [Prunlet.RecordlessE2E.FixtureNative]::WriteCaseSensitiveFile((Join-Path $p 'Case.txt'),$utf8.GetBytes('upper'));[Prunlet.RecordlessE2E.FixtureNative]::WriteCaseSensitiveFile((Join-Path $p 'case.txt'),$utf8.GetBytes('lower'));$before=Snapshot-R $p;Assert-R ($before.Count-eq3-and$before[1].Id-cne$before[2].Id) 'Distinct case-sensitive names not established';$prior=Before-BinR $before;$r=Delete-R $s @($p) -Recursive;$script:observed.recycle=$r
  if($r.exitCode-eq0){Assert-WireR $r @($p) @('recycled');$null=Restore-BinR $s $p $before $prior}else{Assert-R ($r.json.items[0].status-in@('failed','ambiguous')) 'Case-sensitive refusal had an unknown result';$null=Assert-SnapshotR $p $before;$script:observed.outcome='native Shell refusal preserved both names and native proofs'};No-FileRecordsR $s
 }
 Case-R 'cli-protected-deny-acl-native-windows-roundtrip' {$s=New-ScopeR 'protected-acl';$p=File-R $s 'protected';$acl=Get-Acl -LiteralPath $p;$acl.SetAccessRuleProtection($true,$true);$guests=[Security.Principal.SecurityIdentifier]::new('S-1-5-32-546');$deny=[Security.AccessControl.FileSystemAccessRule]::new($guests,[Security.AccessControl.FileSystemRights]::ReadData,[Security.AccessControl.AccessControlType]::Deny);$acl.AddAccessRule($deny);Set-Acl -LiteralPath $p -AclObject $acl;$before=Snapshot-R $p;$prior=Before-BinR $before;$r=Delete-R $s @($p);Assert-WireR $r @($p) @('recycled');Assert-R ($r.exitCode-eq0) 'Protected/Deny fixture recycle failed';$null=Restore-BinR $s $p $before $prior}
 Case-R 'cli-mcp-lock-over-sixty-seconds-progress-eof' {
  $s=New-ScopeR 'long-lock';$paths=@((File-R $s 'cli'),(File-R $s 'mcp'));$proofs=@($paths|ForEach-Object {,(Snapshot-R $_)});$priors=@($proofs|ForEach-Object {,(Before-BinR $_)});$pathFile=Join-Path $s.root 'cli-paths.json';Save-R $pathFile @($paths[0]);$mcp=Open-McpR $s;Init-McpR $mcp;$cli=$null;$held=$null;$messages=[Collections.Generic.List[object]]::new()
  try{
   $held=[IO.FileStream]::new((Join-Path $s.metadata 'maintenance.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);$clock=[Diagnostics.Stopwatch]::StartNew();$cli=Start-R $ExecutablePath $s.config @('delete','--paths-file',$pathFile)
   $request=@{jsonrpc='2.0';id=10;method='tools/call';params=@{name='delete_files';arguments=@{paths=@($paths[1])};_meta=@{progressToken='recordless-lock-token'}}};$mcp.process.StandardInput.WriteLine(($request|ConvertTo-Json -Depth 10 -Compress));$mcp.process.StandardInput.Flush();$lineTask=$mcp.process.StandardOutput.ReadLineAsync()
   while($clock.ElapsedMilliseconds-lt65000){if($lineTask.IsCompleted){$line=$lineTask.GetAwaiter().GetResult();Assert-R ($null-ne$line) 'MCP ended during exclusive wait';$message=$line|ConvertFrom-Json -AsHashtable -Depth 50;$messages.Add($message);Assert-R (!$message.ContainsKey('id')) 'MCP responded before exclusive lock release';Assert-R ($message.method-ceq'notifications/progress'-and$message.params.progressToken-ceq'recordless-lock-token') 'Unexpected wait notification/token';$lineTask=$mcp.process.StandardOutput.ReadLineAsync()};Assert-R (!$cli.process.HasExited) 'CLI ended during exclusive wait';[Threading.Thread]::Sleep(25)}
   $script:observed.lockHeldMilliseconds=$clock.ElapsedMilliseconds;$held.Dispose();$held=$null;$reply=Finish-R $cli;$cli=$null;Assert-WireR $reply @($paths[0]) @('recycled');Assert-R ($reply.exitCode-eq0-and$reply.stderr.Length-gt0) 'CLI wait lacked stderr progress or success';$mcp.process.StandardInput.Close();$final=$false
   while($true){Assert-R ($lineTask.Wait(60000)) 'MCP EOF drain timeout';$line=$lineTask.GetAwaiter().GetResult();if($null-eq$line){break};$message=$line|ConvertFrom-Json -AsHashtable -Depth 50;$messages.Add($message);if($message.ContainsKey('id')){Assert-R (!$final-and$message.id-eq10-and!$message.result.isError) 'MCP final response invalid';$wire=$message.result.content[0].text|ConvertFrom-Json -AsHashtable -Depth 30;Assert-WireR @{json=$wire} @($paths[1]) @('recycled');$final=$true}else{Assert-R (!$final-and$message.method-ceq'notifications/progress'-and$message.params.progressToken-ceq'recordless-lock-token') 'Unexpected token or progress after final response'};$lineTask=$mcp.process.StandardOutput.ReadLineAsync()}
   Assert-R ($final-and@($messages|Where-Object method -CEQ 'notifications/progress').Count-ge2) 'MCP progress/final evidence missing';$script:observed.messages=@($messages);$script:observed.cli=$reply;Close-McpR $mcp;$mcp=$null
   foreach($i in 0..1){$null=Restore-BinR $s $paths[$i] $proofs[$i] $priors[$i]}
  }finally{if($held){$held.Dispose()};if($cli){$null=Finish-R $cli};if($mcp){Close-McpR $mcp}}
 }
